query:
query CatalogCards($skus: [ID!]!) {
  products(skus: $skus) {
    sku
    name
    price {
      amountMinor
      currency
      __typename
    }
    merchant {
      id
      name
      city
      __typename
    }
    availability {
      status
      quantity
      __typename
    }
    __typename
  }
}
